#include <stdio.h>
#include <unistd.h>

int main() {
    // Output is buffered by default
    printf("Example 1... ");
    // sleep(2); // Wait 2 sec

    // Manually flush buffer
    fflush(stdout);
    printf("Printed immediately!\n");

    // Line Buffering: \n automatically flushes
    printf("Example 2 with newline\n");

    return 0;
}
